# Basic linear search — first occurrence
def linear_search(arr, target):
    for i, val in enumerate(arr):
        if val == target:
            return i       # found — return index
    return -1              # not found

print(linear_search([4, 2, 7, 1, 9, 3], 7))   # 2
print(linear_search([4, 2, 7, 1, 9, 3], 5))   # -1

# Find ALL occurrences
def linear_search_all(arr, target):
    return [i for i, val in enumerate(arr) if val == target]

print(linear_search_all([1, 2, 3, 2, 4, 2], 2))  # [1, 3, 5]

# Search with condition — first element > 5
def search_condition(arr, condition):
    for i, val in enumerate(arr):
        if condition(val):
            return i
    return -1

print(search_condition([1, 3, 7, 2, 9], lambda x: x > 5))  # 2

# Search in 2D list — return (row, col)
def search_2d(matrix, target):
    for i, row in enumerate(matrix):
        for j, val in enumerate(row):
            if val == target:
                return (i, j)
    return None

matrix = [[1,2,3],[4,5,6],[7,8,9]]
print(search_2d(matrix, 5))   # (1, 1)
print(search_2d(matrix, 10))  # None

# Search in string
def find_char(s, char):
    for i, c in enumerate(s):
        if c == char:
            return i
    return -1

